1	const WIDTH = 480;
2	const HEIGHT = 320;
3	
4	const BALL_RADIUS = 6;
5	const SERVE = { vx: 40, vy: 240 };
6	const PADDLE_SPEED = 360;
7	const MAX_BOUNCE_ANGLE = Math.PI / 3;
8	
9	const BRICK_ROWS = 3;
10	const BRICK_COLS = 8;
11	const BRICK_WIDTH = 50;
12	const BRICK_HEIGHT = 14;
13	const BRICK_GAP = 6;
14	const BRICK_TOP = 40;
15	
16	const LIGHT = { paper: "#f3ede2", ink: "#1f1b16", accent: "#c8432b", bricks: ["#2c7a6f", "#c4841a", "#6b7a8c"] };
17	const DARK = { paper: "#17150f", ink: "#eee6d6", accent: "#ef6a4f", bricks: ["#4fb3a4", "#e3a640", "#93a3b6"] };
18	
19	function clamp(value, min, max) {
20	  return Math.max(min, Math.min(max, value));
21	}
22	
23	function makeBricks() {
24	  const rowWidth = BRICK_COLS * BRICK_WIDTH + (BRICK_COLS - 1) * BRICK_GAP;
25	  const left = (WIDTH - rowWidth) / 2;
26	  const bricks = [];
27	  for (let row = 0; row < BRICK_ROWS; row++) {
28	    for (let col = 0; col < BRICK_COLS; col++) {
29	      const x = left + col * (BRICK_WIDTH + BRICK_GAP);
30	      const y = BRICK_TOP + row * (BRICK_HEIGHT + BRICK_GAP);
31	      bricks.push({ x, y, width: BRICK_WIDTH, height: BRICK_HEIGHT, row, alive: true });
32	    }
33	  }
34	  return bricks;
35	}
36	
37	function serve(ball) {
38	  ball.x = WIDTH / 2;
39	  ball.y = HEIGHT / 2;
40	  ball.vx = SERVE.vx;
41	  ball.vy = SERVE.vy;
42	}
43	
44	function createState() {
45	  const ball = { x: 0, y: 0, vx: 0, vy: 0, radius: BALL_RADIUS };
46	  serve(ball);
47	  const paddle = { x: 0, y: HEIGHT - 24, width: 80, height: 10 };
48	  paddle.x = (WIDTH - paddle.width) / 2;
49	  return { ball, paddle, bricks: makeBricks(), score: 0 };
50	}
51	
52	function setPaddleCentre(state, x) {
53	  const paddle = state.paddle;
54	  paddle.x = clamp(x - paddle.width / 2, 0, WIDTH - paddle.width);
55	}
56	
57	function movePaddle(state, direction, dt) {
58	  const paddle = state.paddle;
59	  paddle.x = clamp(paddle.x + direction * PADDLE_SPEED * dt, 0, WIDTH - paddle.width);
60	}
61	
62	function circleHitsRect(ball, rect) {
63	  const nearestX = clamp(ball.x, rect.x, rect.x + rect.width);
64	  const nearestY = clamp(ball.y, rect.y, rect.y + rect.height);
65	  const dx = ball.x - nearestX;
66	  const dy = ball.y - nearestY;
67	  return dx * dx + dy * dy < ball.radius * ball.radius;
68	}
69	
70	function hitsPaddle(ball, paddle) {
71	  if (ball.vy <= 0) return false;
72	  const level = ball.y + ball.radius >= paddle.y && ball.y - ball.radius <= paddle.y + paddle.height;
73	  return level && Math.abs(ball.x - paddle.x) < paddle.width / 2 + ball.radius;
74	}
75	
76	function bounceOffPaddle(ball, paddle) {
77	  const centre = paddle.x + paddle.width / 2;
78	  const offset = clamp((ball.x - centre) / (paddle.width / 2), -1, 1);
79	  const speed = Math.hypot(ball.vx, ball.vy);
80	  const angle = offset * MAX_BOUNCE_ANGLE;
81	  ball.vx = speed * Math.sin(angle);
82	  ball.vy = -speed * Math.cos(angle);
83	  ball.y = paddle.y - ball.radius;
84	}
85	
86	function bounceOffBrick(ball, brick) {
87	  const overlapX = Math.min(ball.x + ball.radius - brick.x, brick.x + brick.width - (ball.x - ball.radius));
88	  const overlapY = Math.min(ball.y + ball.radius - brick.y, brick.y + brick.height - (ball.y - ball.radius));
89	  if (overlapX < overlapY) ball.vx = -ball.vx;
90	  else ball.vy = -ball.vy;
91	}
92	
93	function step(state, dt) {
94	  const { ball, paddle } = state;
95	  ball.x += ball.vx * dt;
96	  ball.y += ball.vy * dt;
97	
98	  if (ball.x - ball.radius < 0) {
99	    ball.x = ball.radius;
100	    ball.vx = Math.abs(ball.vx);
101	  } else if (ball.x + ball.radius > WIDTH) {
102	    ball.x = WIDTH - ball.radius;
103	    ball.vx = -Math.abs(ball.vx);
104	  }
105	  if (ball.y - ball.radius < 0) {
106	    ball.y = ball.radius;
107	    ball.vy = Math.abs(ball.vy);
108	  }
109	
110	  const brick = state.bricks.find((b) => b.alive && circleHitsRect(ball, b));
111	  if (brick) {
112	    brick.alive = false;
113	    state.score += 10;
114	    bounceOffBrick(ball, brick);
115	    if (state.bricks.every((b) => !b.alive)) state.bricks = makeBricks();
116	  }
117	
118	  if (hitsPaddle(ball, paddle)) bounceOffPaddle(ball, paddle);
119	
120	  if (ball.y - ball.radius > HEIGHT) serve(ball);
121	  return state;
122	}
123	
124	function draw(ctx, state, colours) {
125	  ctx.fillStyle = colours.paper;
126	  ctx.fillRect(0, 0, WIDTH, HEIGHT);
127	
128	  for (const brick of state.bricks) {
129	    if (!brick.alive) continue;
130	    ctx.fillStyle = colours.bricks[brick.row % colours.bricks.length];
131	    ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
132	  }
133	
134	  const { ball, paddle } = state;
135	  ctx.fillStyle = colours.accent;
136	  ctx.fillRect(paddle.x, paddle.y, paddle.width, paddle.height);
137	  ctx.beginPath();
138	  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
139	  ctx.fill();
140	
141	  ctx.fillStyle = colours.ink;
142	  ctx.font = "14px ui-monospace, Menlo, Consolas, monospace";
143	  ctx.textBaseline = "top";
144	  ctx.fillText("Score " + state.score, 12, 12);
145	}
146	
147	function start(canvas) {
148	  const ctx = canvas.getContext("2d");
149	  const dpr = window.devicePixelRatio || 1;
150	  canvas.width = WIDTH * dpr;
151	  canvas.height = HEIGHT * dpr;
152	  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
153	  canvas.style.touchAction = "none";
154	  if (!canvas.hasAttribute("tabindex")) canvas.tabIndex = 0;
155	
156	  const darkMode = window.matchMedia("(prefers-color-scheme: dark)");
157	  const state = createState();
158	  const keys = { left: false, right: false };
159	  let last = null;
160	  let frame = 0;
161	
162	  function onPointer(event) {
163	    const rect = canvas.getBoundingClientRect();
164	    setPaddleCentre(state, ((event.clientX - rect.left) / rect.width) * WIDTH);
165	  }
166	
167	  function onKey(event) {
168	    const down = event.type === "keydown";
169	    const key = event.key.toLowerCase();
170	    if (key === "arrowleft" || key === "a") keys.left = down;
171	    else if (key === "arrowright" || key === "d") keys.right = down;
172	    else return;
173	    event.preventDefault();
174	  }
175	
176	  function onBlur() {
177	    keys.left = keys.right = false;
178	  }
179	
180	  function tick(time) {
181	    const dt = last === null ? 0 : Math.min((time - last) / 1000, 1 / 30);
182	    last = time;
183	    movePaddle(state, (keys.right ? 1 : 0) - (keys.left ? 1 : 0), dt);
184	    step(state, dt);
185	    draw(ctx, state, darkMode.matches ? DARK : LIGHT);
186	    frame = requestAnimationFrame(tick);
187	  }
188	
189	  const listeners = [["pointermove", onPointer], ["pointerdown", onPointer], ["keydown", onKey], ["keyup", onKey], ["blur", onBlur]];
190	  for (const [type, fn] of listeners) canvas.addEventListener(type, fn);
191	  frame = requestAnimationFrame(tick);
192	
193	  return {
194	    stop() {
195	      cancelAnimationFrame(frame);
196	      for (const [type, fn] of listeners) canvas.removeEventListener(type, fn);
197	    },
198	  };
199	}
200	
201	if (typeof module !== "undefined") {
202	  module.exports = { WIDTH, HEIGHT, createState, step, setPaddleCentre, movePaddle, circleHitsRect, hitsPaddle };
203	}
