7	test("ball bounces off the left wall", () => {
8	  const state = createState();
9	  Object.assign(state.ball, { x: 8, y: 200, vx: -240, vy: 0 });
10	  step(state, FRAME);
11	  assert.ok(state.ball.vx > 0);
12	  assert.ok(state.ball.x >= state.ball.radius);
13	});
