15	test("hitting a brick breaks it and scores", () => {
16	  const state = createState();
17	  const brick = state.bricks[state.bricks.length - 1];
18	  Object.assign(state.ball, {
19	    x: brick.x + brick.width / 2,
20	    y: brick.y + brick.height + state.ball.radius + 1,
21	    vx: 0,
22	    vy: -240,
23	  });
24	  step(state, FRAME);
25	  assert.equal(brick.alive, false);
26	  assert.equal(state.score, 10);
27	  assert.ok(state.ball.vy > 0);
