50	test("a missed ball is served again from the centre", () => {
51	  const state = createState();
52	  Object.assign(state.ball, { x: 30, y: HEIGHT + 10, vx: 0, vy: 240 });
53	  step(state, FRAME);
54	  assert.equal(state.ball.x, WIDTH / 2);
